import { readdirSync, writeFileSync } from "node:fs";

const root = new URL("../../src/translations/", import.meta.url);

const languages = readdirSync(root)
	.filter((name) => name.endsWith(".json"))
	.map((name) => [name.replace(/\.json$/, ""), languageName(name)]);

export const updateLanguages = () =>
	writeFileSync(
		new URL("index.ts", root),
		`
// This file is generated by ‘bs/helpers/languages.js’! Use NAME key in JSON files.

export const languages= ${JSON.stringify(Object.fromEntries(languages), null, "\t")} as const;

export type Language= keyof typeof languages;
`.trim(),
	);

import { readFileSync } from "node:fs";

function languageName(name) {
	const file = JSON.parse(readFileSync(new URL(name, root)).toString());
	return file.NAME;
}
